# Let me solve this with a simple backtracking or greedy approach
# Assign each number 1..21 to subset 0, 1, or 2
# Each subset must sum to 77

def solve():
    numbers = list(range(1, 22))  # 1 to 21
    assignment = [0] * 21
    sums = [0, 0, 0]
    target = 77

    def backtrack(idx):
        if idx == 21:
            return all(s == target for s in sums)

        num = numbers[idx]
        for subset in range(3):
            if sums[subset] + num <= target:
                sums[subset] += num
                assignment[idx] = subset
                if backtrack(idx + 1):
                    return True
                sums[subset] -= num
        return False

    if backtrack(0):
        return assignment
    return None

result = solve()
print(result)
if result:
    # Verify
    subsets = [[], [], []]
    for i, a in enumerate(result):
        subsets[a].append(i + 1)
    for s in subsets:
        print(f"Subset: {s}, sum = {sum(s)}")
